# Fixed validation19 clean audit, all methods/seeds, no sealed outcome.
import os,sys,json,base64,zlib,subprocess,hashlib,requests
from pathlib import Path
code=Path('/kaggle/working/code');code.mkdir(exist_ok=True)
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 p=code/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value)
os.environ['PYTHONPATH']=str(code/'src')+':'+str(code)
out=Path('/kaggle/working/out');out.mkdir(exist_ok=True)
revision='05458b8 plus committed audit packaging overlay'
(out/'runner_provenance.json').write_text(json.dumps(dict(seed=20261013,git_commit=revision,runner_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),scope='fixed first validation19 character attack/optimization audit, all3seeds; not population rates'),indent=2))
result=subprocess.run([sys.executable,'-m','pytest','-q',str(code/'tests')],cwd=code,text=True,capture_output=True)
(out/'pytest.txt').write_text(result.stdout+result.stderr);print(result.stdout,flush=True)
if result.returncode:raise RuntimeError('integration tests failed before outcome inspection')
root=Path('/kaggle/input')
def unique(name):
 matches=list(root.rglob(name))
 if len(matches)!=1:raise RuntimeError(f'Expected one own artifact {name}, found{len(matches)}')
 return matches[0]
proof=json.loads(unique('reference_calibration_complete.json').read_text())
if proof['subject']!=19 or proof['seeds']!=[20261013,20261014,20261015]:raise RuntimeError('fixed complete calibration proof required')
schedule=unique('schedule.mat');raw=Path('/kaggle/working/sess01_subj19_EEG_ERP.mat')
url='https://s3.ap-northeast-1.wasabisys.com/gigadb-datasets/live/pub/10.5524/100001_101000/100542/session1/s19/'+raw.name
with requests.get(url,stream=True,timeout=(30,300)) as response:
 response.raise_for_status()
 with raw.open('wb') as handle:
  for chunk in response.iter_content(1024*1024):handle.write(chunk)
for seed in proof['seeds']:
 subprocess.run([sys.executable,str(code/'scripts/audit_openbmi_attacks.py'),'--template',str(unique(f'source_template_seed{seed}.pt')),'--reference-json',str(unique(f'references_seed{seed}.json')),'--checkpoint',str(unique(f'source_seed{seed}.pt')),'--references',str(unique(f'references_seed{seed}.npz')),'--calibration',str(unique(f'calibration_s19_seed{seed}.json')),'--user-preprocessor',str(unique(f'user_preprocessor_s19_seed{seed}.pt')),'--raw-file',str(raw),'--schedule',str(schedule),'--out-dir',str(out),'--subject','19','--seed',str(seed),'--git-commit',revision],check=True)
raw.unlink()
(out/'attack_audit_complete.json').write_text(json.dumps(dict(seed=20261013,seeds=proof['seeds'],subject=19,scope='single fixed development character optimization audit; no sealed/population outcome'),indent=2))
